import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  /** Optional render prop for a fully custom fallback. Receives the error and a reset callback. */
  renderFallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ErrorBoundary] Uncaught render error", {
      message: error.message,
      name: error.name,
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (!error) return this.props.children;

    if (this.props.renderFallback) {
      return this.props.renderFallback(error, this.reset);
    }

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.message}>{error.message}</p>
        {componentStack && (
          <details style={styles.details}>
            <summary style={styles.summary}>Component stack</summary>
            <pre style={styles.stack}>{componentStack}</pre>
          </details>
        )}
        <button onClick={this.reset} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "1.5rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    background: "#fff1f2",
    fontFamily: "sans-serif",
    maxWidth: "600px",
  },
  heading: {
    margin: "0 0 0.5rem",
    color: "#b91c1c",
    fontSize: "1.125rem",
  },
  message: {
    margin: "0 0 1rem",
    color: "#991b1b",
    fontSize: "0.9rem",
  },
  details: {
    marginBottom: "1rem",
  },
  summary: {
    cursor: "pointer",
    color: "#6b7280",
    fontSize: "0.8rem",
  },
  stack: {
    marginTop: "0.5rem",
    padding: "0.75rem",
    background: "#fee2e2",
    borderRadius: "0.25rem",
    fontSize: "0.75rem",
    whiteSpace: "pre-wrap",
    overflowX: "auto",
    color: "#7f1d1d",
  },
  button: {
    padding: "0.5rem 1rem",
    background: "#b91c1c",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};

